import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('BebasNeue');

// Load the high-impact condensed sans-serif font
const { fontFamily } = loadFont();

// Single inline schema definition


export type DropCountdownProps = Record<string, any>;

const DropCountdown: React.FC<DropCountdownProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = true,
  durationInSeconds = 5,
  startValue = 2340000,
  endValue = 624000,
  textColor = "#000000",
  maxFontSizeRatio = 0.18,
  minFontSizeRatio = 0.09,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dynamic Background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline configuration in frames
  const totalFrames = durationInSeconds * fps;
  const slamStart = 0;
  const slamEnd = Math.floor(0.12 * totalFrames);
  const holdEnd = Math.floor(0.22 * totalFrames);
  const dropStart = holdEnd;
  const dropEnd = Math.floor(0.72 * totalFrames);
  const pulseStart = dropEnd;
  const pulseEnd = Math.floor(0.85 * totalFrames);
  const fadeStart = Math.floor(0.90 * totalFrames);
  const fadeEnd = totalFrames;

  // 1. Slam / Impact Entry (0% - 12%)
  const slamSpring = spring({
    frame,
    fps,
    config: {
      stiffness: 140,
      damping: 12,
      mass: 1.1,
    },
    durationInFrames: slamEnd - slamStart,
  });

  const slamScale = interpolate(slamSpring, [0, 1], [3, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const slamBlur = interpolate(slamSpring, [0, 1], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const slamOpacity = interpolate(slamSpring, [0, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Melting Drop / Shrink Countdown (22% - 72%)
  const dropProgress = Math.max(0, Math.min(1, (frame - dropStart) / (dropEnd - dropStart)));
  // High acceleration cubic ease-out to start fast then settle slowly
  const easeOutCubic = 1 - Math.pow(1 - dropProgress, 3);

  const currentValue = frame < dropStart
    ? startValue
    : frame > dropEnd
    ? endValue
    : Math.round(startValue + (endValue - startValue) * easeOutCubic);

  // Dynamic position (top-heavy 35% height to bottom-heavy 72% height)
  const currentY = interpolate(easeOutCubic, [0, 1], [height * 0.35, height * 0.72], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Dynamic font size (shrinks in proportion to the value drop)
  const calculatedMaxFontSize = width * maxFontSizeRatio;
  const calculatedMinFontSize = width * minFontSizeRatio;
  const currentFontSize = interpolate(
    easeOutCubic,
    [0, 1],
    [calculatedMaxFontSize, calculatedMinFontSize],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Character distortion / Liquid stretch during drop
  // Peaking at t = 0.5 where the drop speed is maximized
  const turbulence = Math.sin(dropProgress * Math.PI);
  const stretchY = 1 + 0.35 * turbulence; // stretches vertically
  const stretchX = 1 - 0.15 * turbulence; // compresses horizontally

  // 3. Heartbeat Pulse (72% - 85%)
  const pulseProgress = Math.max(0, Math.min(1, (frame - pulseStart) / (pulseEnd - pulseStart)));
  // Double beat (lub-dub) curve
  const pulseScale = interpolate(
    pulseProgress,
    [0, 0.15, 0.3, 0.45, 0.6, 0.8, 1],
    [1, 1.15, 1.02, 1.10, 1.0, 1.0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 4. Fade Out (90% - 100%)
  const fadeOutOpacity = interpolate(frame, [fadeStart, fadeEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const globalOpacity = frame < slamEnd ? slamOpacity : fadeOutOpacity;
  const scale = frame < holdEnd ? slamScale : pulseScale;
  const blur = frame < holdEnd ? slamBlur : 0;

  // Format number as currency string
  const formattedString = "$" + currentValue.toLocaleString("en-US");
  const characters = formattedString.split("");

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: currentY,
          transform: `translateY(-50%) scale(${scale})`,
          opacity: globalOpacity,
          filter: `blur(${blur}px)`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          perspective: 1200,
          transition: "none",
        }}
      >
        <div
          style={{
            fontFamily,
            fontSize: currentFontSize,
            fontWeight: "900",
            color: textColor,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            letterSpacing: "-0.02em",
            userSelect: "none",
            transition: "none",
          }}
        >
          {characters.map((char, index) => {
            // Apply unique pseudo-random 3D tumble physics during peak drop
            const seedY = random(`y-${index}`);
            const seedRotX = random(`rotX-${index}`);
            const seedRotY = random(`rotY-${index}`);
            const seedRotZ = random(`rotZ-${index}`);

            const charTransY = (seedY - 0.5) * 110 * turbulence;
            const charRotX = (seedRotX - 0.5) * 140 * turbulence;
            const charRotY = (seedRotY - 0.5) * 70 * turbulence;
            const charRotZ = (seedRotZ - 0.5) * 40 * turbulence;

            return (
              <span
                key={`${char}-${index}`}
                style={{
                  display: "inline-block",
                  transform: `translate3d(0px, ${charTransY}px, 0px) rotateX(${charRotX}deg) rotateY(${charRotY}deg) rotateZ(${charRotZ}deg) scale(${stretchX}, ${stretchY})`,
                  transformOrigin: "center center",
                  whiteSpace: "pre",
                  transition: "none",
                }}
              >
                {char}
              </span>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DropCountdown;